export function solve(text) {
  const [topic, payload = ''] = text.split('::');
  return {topic, payload};
}

export async function solve(jobs) {
  const settled = await Promise.allSettled(jobs.map(j => j.status === 'rejected' ? Promise.reject(j.reason) : Promise.resolve(j.value)));
  return {successes:settled.filter(j => !j.reason).map(j => j.value ?? null), failures:settled.filter(j => j.reason).map(j => j.reason)};
}

export function solve(graph) {
  const seen = new Set();
  function visit(node) {
    if (seen.has(node)) return true;
    seen.add(node);
    return (graph[node] || []).some(visit);
  }
  return Object.keys(graph).some(visit);
}

export function solve(line) {
  const [key, value = ''] = line.split('=');
  return {key, value};
}

export async function solve(operations) {
  const results = await Promise.allSettled(operations.map(op => op.reject ? Promise.reject(op.payload) : Promise.resolve(op.payload)));
  return results.map(r => r.reason ? {state:'failed',reason:r.reason} : {state:'ok',value:r.value ?? null});
}

export function solve(edges) {
  const graph = {};
  for (const [a,b] of edges) (graph[a] ||= []).push(b);
  const seen = new Set();
  function visit(n) {
    if (seen.has(n)) return true;
    seen.add(n);
    return (graph[n] || []).some(visit);
  }
  return Object.keys(graph).some(visit);
}

export function solve(booking, slot) {
  return booking[0] <= slot[1] && slot[0] <= booking[1];
}

export function solve(ids, cursor, limit) {
  const start = cursor === null ? 0 : ids.indexOf(cursor) + 1;
  return ids.slice(start,start + limit);
}
